{
  "findings": [
    {
      "check_id": "CKV_AWS_203",
      "title": "Ensure ECS task definition uses non-default network mode",
      "resource": "aws_ecs_task_definition.service",
      "severity": "LOW",
      "explanation": "The ECS task definition does not specify a network mode, defaulting to 'bridge', which may not be suitable for all use cases."
    }
  ],
  "patched_code": "resource "aws_ecs_task_definition" "service" {
  family                = "service"
  container_definitions = file("task-definitions/service.json")
  network_mode          = "awsvpc"

  volume {
    name = "efs-vol-1"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.fs1.id
      root_directory          = "/opt/data1"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
      authorization_config {
        access_point_id = aws_efs_access_point.test1.id
        iam             = "ENABLED"
      }
    }
  }

  volume {
    name = "efs-vol-2"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.fs2.id
      root_directory          = "/opt/data2"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
      authorization_config {
        access_point_id = aws_efs_access_point.test2.id
        iam             = "ENABLED"
      }
    }
  }
}
",
  "fix_summary": "Added 'network_mode = "awsvpc"' to the ECS task definition to use a more secure and modern networking mode."
}
